SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(8*10^9);Alarm(1700);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C54/inputs/pair_af_place_linear.m";root:="work/deg10/continuation_20261031b/C54/";dy:=eval Read(root cat "dyadic_rigidity_v2.m");X:=MDX1(27,GF(5));C:=Curve(X);F0,mp:=AlgorithmicFunctionField(FunctionField(C));F:=RationalExtensionRepresentation(F0);assert Genus(F)eq 13;k:=GF(5);PK:=PolynomialRing(k);BC:=[F!mp(v):v in X`_coordinates];XY:=[F!mp(v):v in X`_coordinates_xy];cs:=Cusps(X);sigs:=[CuspSignature(X,p):p in cs];cp:=[Support(FunctionFieldDivisor(Divisor(cs[Index(sigs,sg)])))[1]:sg in dy[3]];assert[Degree(p):p in cp]eq dy[4];A:=Divisor(cp[Index(dy[4],1)]);G,_,phi:=ClassGroup(F:ReductionDivisor:=A,Proof:=true);assert Invariants(G)eq[3,3,342175446,0];cg:=[phi(Divisor(p)-Degree(p)*A):p in cp];Gold:=AbelianGroup([3,3,52497]);Z:=FreeAbelianGroup(#cp);hOld:=hom<Z->Gold|[Gold!v[1..3]:v in dy[6]]>;hNew:=hom<Z->G|cg>;assert #Image(hOld)eq 472473 and #Image(hNew)eq 472473;cv:=hom<Gold->G|[hNew(Gold.i@@hOld):i in[1..3]]>;assert #Image(cv)eq 472473 and &and[cv(hOld(Z.i))eq cg[i]:i in[1..#cp]];OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);B:=BaseField(F);
function Rat(v)return B!(PK!v[1])/B!(PK!v[2]);end function;
function FF(v)return F![Rat(z):z in v];end function;
function DP(v)O:=v[2]eq 1 select OF else OI;I:=ideal<O|[FF(z):z in v[3]]>;assert IsPrime(I);p:=Place(I);assert Degree(p)eq v[1];return p;end function;
function DD(v)return &+[DivisorGroup(F)|z[2]*Divisor(DP(z[1])):z in v];end function;
function Key(vals)
 KK:=Parent(vals[1]);e:=LCM([Degree(MinimalPolynomial(v,k)):v in vals]);chosen:=[];for zz in[[1,0],[0,1]]cat[[1,n]:n in[1..4]]do gen:=zz[1]*vals[1]+zz[2]*vals[2];pol:=MinimalPolynomial(gen,k);if Degree(pol)eq e then chosen:=zz;break;end if;end for;assert #chosen eq 2;MM:=Matrix(k,[Eltseq(gen^i,k):i in[0..e-1]]);co:=[Eltseq(Solution(MM,Vector(k,Eltseq(v,k)))):v in vals];return[e]cat chosen cat[Integers()!z:z in Coefficients(pol)]cat &cat[[Integers()!z:z in rr]:rr in co];
end function;
function FromKey(ky)
 e:=ky[1];KK:=ext<k|PK!ky[4..4+e]>;gg:=KK.1;bb:=Evaluate(PK!ky[5+e..4+2*e],gg);cc:=Evaluate(PK!ky[5+2*e..4+3*e],gg);EE:=EllipticCurve([KK|1-cc,-bb,-bb,0,0]);PP:=EE![0,0];assert 27*PP eq EE!0 and 9*PP ne EE!0;pt:=C48PairAFPlaceLinear(XY,TateNormalForm_xy(EE,PP));assert Degree(pt)eq e and Key([Evaluate(v,pt):v in BC])eq ky;return pt;
end function;
